    /**
     * Función que se utiliza para cargar a estructura del DPA
     *
     * @param int $id
     * @param int $idpais Identificador de país
     *
     * @return array
     */
    static function cargarEstructura($id, $idpais, $nombredpa = '')
    {

        $q = Doctrine_Query::create();

        $where = ($id == 'idpadre')
            ? "a.iddpt = a.idpadre and a.idpais = $idpais and a.fechafin is null"
            :
            "a.idpadre = $id  and a.idpais = $idpais and a.iddpt<>a.idpadre and a.fechafin is null";

        if ($nombredpa) {
            $where .= " and a.denominacion ilike '%$nombredpa%'";
        }

        $result = $q->select(
            'a.iddpt,a.iddpt id,a.denominacion, a.denominacion text,a.idpadre, a.abreviatura,a.abreviatura alias,
            a.fechafin, a.fechainicio, a.idpais,a.idnivelestructural,a.codigo, b.idconceptonivel,k.idconceptonivel,
            (a.ordender - a.ordenizq = 1) as leaf,p.nombrepais'
        )
            ->from('NomDpa a')
            ->innerJoin('a.NomNivelestructural b on a.idnivelestructural=b.idnivelestructural')
            ->innerJoin('b.NomConceptonivel k ')
            ->leftJoin('a.NomPais p')
            ->where($where)
            ->orderby('iddpt')
            ->setHydrationMode(Doctrine::HYDRATE_ARRAY)
            ->execute();
        return $result;
    }

    /**
     * Función que se utiliza para retornar la cantidad de estructuras de la base legal
     *
     * @param int $id
     * @param int $idpais Identificador de país
     *
     * @return int
     */
    static function cantidadEstructuras($id, $idpais, $filter = NULL)
    {
        $q = Doctrine_Query::create();
        $where = ($id == 'idpadre') ? "iddpt = idpadre  and idpais=$idpais"
            : "idpadre = $id and iddpt<>idpadre and idpais=$idpais";
        
        if(!is_null($filter)){
            $array = array(
                "lower(codigo) ILIKE lower('%$filter%')",
                "lower(denominacion) ILIKE lower('%$filter%')",
                "lower(abreviatura) ILIKE lower('%$filter%')"
//                "lower(cast(fechafin as text)) ILIKE lower('%$filter%')",
//                "lower(cast(fechainicio as text)) ILIKE lower('%$filter%')",
            );
            $where .= ' AND ('.implode(' OR ', $array).')';
        }
        
        $result = $q->from('NomDpa')->where($where)->count();
        return $result;
    }

    /**
     * Función que se utiliza para retornar la cantidad de estructuras de la base legal
     *
     * @param int $id
     * @param int $start Comienzo inferior
     * @param int $limit Límite superior
     *
     * @return array
     */
    static function valoresEstructuraplan($id, $start, $limit, $idpais, $filter = NULL)
    {
//        "lower(cast($key as text)) ILIKE lower('%$filter%')
        
        $q = Doctrine_Query::create();
        $where = ($id == 'idpadre') ? "iddpt = idpadre and idpais=$idpais"
            : "idpadre = $id and iddpt<>idpadre and idpais=$idpais";
        
        if(!is_null($filter)){
            $array = array(
                "lower(codigo) ILIKE lower('%$filter%')",
                "lower(denominacion) ILIKE lower('%$filter%')",
                "lower(abreviatura) ILIKE lower('%$filter%')"
//                "lower(cast(fechafin as text)) ILIKE lower('%$filter%')",
//                "lower(cast(fechainicio as text)) ILIKE lower('%$filter%')",
            );
            $where .= ' AND ('.implode(' OR ', $array).')';
        }
        
        $result = $q->select(
            'dpa.iddpt as id, dpa.denominacion as text,dpa.idpadre, dpa.abreviatura, dpa.fechafin, dpa.fechainicio, dpa.codigo,
            (dpa.ordender - dpa.ordenizq = 1) as leaf,ncn.denominacion as conceptonivel'
        )
            ->from('NomDpa dpa')->leftJoin('dpa.NomNivelestructural nve')->innerJoin('nve.NomConceptonivel ncn')->where($where)->offset($start)->limit($limit)->orderby('iddpt')->execute()->toArray();
        return $result;
    }

    /**
     * Para que devuelve los padres de un nodo determinado
     *
     * @param int $iddpt Identificador de División Político Administrativa
     *
     * @return array
     */
    static function buscarPadres($iddpt)
    {
        $mg = Doctrine_Manager::getInstance();
        $conn = $mg->getConnection('configsecodena');
        $sql = "SELECT n.iddpt AS iddpt, n.denominacion AS text,n.idnivelestructural,
                (n.ordender - n.ordenizq) = 1 as leaf, n.idpadre, n.iddpt AS id
                FROM mod_datosmaestros.nom_dpt n
                WHERE (ordenizq <= (select ordenizq from mod_datosmaestros.nom_dpt
                where iddpt=$iddpt) AND ordender >= (select ordender from mod_datosmaestros.nom_dpt
                where iddpt=$iddpt)) ORDER BY n.ordenizq";

        return $conn->fetchAll($sql);
    }

