    static function getRutaDPT($iddpt, $completo = false)
    {
      $_dpt   = Doctrine::getTable('NomDpa')->find($iddpt);
      $_rama  = '';
      $_datos = '';
      if ($_dpt) {
        $q = Doctrine_Query::create();
        $q->select('*')->from('NomDpa sec')->where(
          "ordenizq <= ? and ordender >= ?", array($_dpt->ordenizq, $_dpt->ordender)
        ) ->orderBy('ordenizq');
        if ($completo) {
          $q->leftJoin('sec.NomNivelestructural ne')->leftJoin('ne.NomConceptonivel c')->addSelect(
            'c.denominacion as concepto'
          );
        }
        $result = $q->setHydrationMode(Doctrine::HYDRATE_ARRAY)->execute();
        foreach ($result as $index => $datos) {
          if ($index == 0) {
            $_pais = Doctrine::getTable('NomPais')->find($result[0]['idpais']);
            if ($_pais) {
              $obj                       = array();
              $obj['denominacion']       = $_pais->nombrepais;
              $obj['concepto']           = 'Pais';
              $obj['idnivelestructural'] = 0;
              $obj['idpais']                 = $_pais->idpais;
              $_datos[]                  = $obj;
              $_rama                     = $_pais->nombrepais;
              $_rama .= '=>' . $datos['denominacion'];
            } else {
              $_rama = $datos['denominacion'];
            }
          } else {
            $_rama .= '=>' . $datos['denominacion'];
          }
          $obj                       = array();
          $obj['denominacion']       = $datos['denominacion'];
          $obj['concepto']           = $datos['concepto'];
          $obj['idnivelestructural'] = $datos['idnivelestructural'];
          $obj['iddpt']                 = $datos['iddpt'];
          $_datos[]                  = $obj;
        }
      }
      if (!$completo) {
        return $_rama;
      } else {
        return $_datos;
      }
    }
    
    /**
     * Función que se utiliza para retornar el elemento pasado su id
     *
     * @param int $iddpt Identificador de División Político Administrativa
     *
     * @return array
     */
    static function getElementoid($iddpt)
    {
        $q = Doctrine_Query::create();
        $result = $q->select(
            'a.iddpt, a.denominacion text,a.idpadre, a.abreviatura, a.fechafin,a.idpais,a.fechainicio, a.codigo,
            (a.ordender - a.ordenizq = 1) as leaf, k.denominacion as tpest'
        )
            ->from('NomDpa a')
            ->innerJoin('a.NomNivelestructural b on a.idnivelestructural=b.idnivelestructural')
            ->innerJoin('b.NomConceptonivel k ')
            ->where("iddpt=?", $iddpt)->execute()->toArray();
        return $result;
    }

    /**
     * Para devolver si el nodo2 es hijo del nodo1
     *
     * @param int $idpadre Identificador padre
     * @param int $idhijo  Identificador hijo
     *
     * @return bool
     */
    static function dimesieshijo($idpadre, $idhijo)
    {
        $q = Doctrine_Query::create();
        $resultpadre = $q->select(
            'iddpt id, denominacion text,idpadre, abreviatura, fechafin, fechainicio, codigo,
            (ordender - ordenizq = 1) as leaf'
        )
            ->from('NomDpa')->where("iddpt=?", $idpadre)->execute()->toArray();
        $resulhijo = $q->select(
            'iddpt id, denominacion text,idpadre, abreviatura, fechafin, fechainicio, codigo,
            (ordender - ordenizq = 1) as leaf'
        )
            ->from('NomDpa')->where("iddpt=?", $idhijo)->execute()->toArray();
        if (($resulhijo [0] ['ordenizq'] > $resultpadre [0] ['ordenizq'])
            && ($resulhijo [0] ['ordender'] < $resultpadre [0] ['ordender'])
        ) {
            return true; //Retorno verdadero si es hijo
        } else {
            return false;
        }
    }

    /**
     * Obtiene los niveles dado el ID de país
     *
     * @param int $idpais Identificador país
     *
     * @return array
     */
    public function obtenerNivelesDadoPais($idpais)
    {
        $mg = Doctrine_Manager::getInstance();
        $conn = $mg->getConnection('configsecodena');
        $sql = "SELECT DISTINCT(n.idnivelestructural) AS idnivelestructural,
                n3.denominacion AS denominacion
                FROM mod_datosmaestros.nom_dpt n
                INNER JOIN mod_configsecodena.nom_nivelestructural n2 ON n.idnivelestructural = n2.idnivelestructural
                INNER JOIN mod_configsecodena.nom_conceptonivel n3 ON 
                n2.idconceptonivel = n3.idconceptonivel WHERE (n.idpais = $idpais)";
        return $conn->fetchAll($sql);
    }

    /**
     * Obtiene el padre
     *
     * @param int $idpadre Identificador padre
     *
     * @return array
     */
    static public function obtenerPadre($idpadre)
    {
        $query = Doctrine_Query::create();
        return $query->select(
            "true expanded, false visitado, iddpt id, denominacion text, ( (ng.ordender - ng.ordenizq) = 1) leaf,iddpt,
             idpadre, ordender, ordenizq"
        )
            ->from('NomDpa ng')->where("ng.iddpt = ?", $idpadre)->setHydrationMode(Doctrine::HYDRATE_ARRAY)->execute();
    }

    /**
     * Obtiene un arreglo de DPA dado los IDs
     *
     * @param array $arrayids arreglo de identificador
     * @param bool  $chk
     *
     * @return array
     */
    static public function getDpaDadoArrayIds($arrayids, $chk = false)
    {
        $checked = ($chk) ? ",false as checked" : "";
        $query = Doctrine_Query::create();
        return $query->select(
            "n.iddpt id, n.iddpt, n.denominacion text, n.denominacion,( (n.ordender - n.ordenizq) = 1) leaf, n.iddpt,
             n.idpadre, n.ordender, n.ordenizq". $checked
        )
            ->from('NomDpa n')
            ->whereIn("n.iddpt", $arrayids)
            ->orderby('n.denominacion')
            ->setHydrationMode(Doctrine::HYDRATE_ARRAY)
            ->execute();
    }

    /**
     * Obtiene un arreglo de DPA dado los IDs de los hijos
     *
     * @param array $strpadres arreglo de identificador hijos
     * @param mixed $node
     * @param bool  $chk
     *
     * @return array
     */
    static public function getDpaDadoArrayIdsHijos($strpadres, $node, $chk = false)
    {
        $query = Doctrine_Query::create();
        $checked = ($chk) ? ",false as checked" : "";
        $padre = ($node == '0') ? ' n.idpadre = n.iddpt ' : " n.idpadre = $node  AND n.iddpt <> $node";

        return $query->select(
            "n.iddpt id, n.denominacion text, ( (n.ordender - n.ordenizq) = 1) leaf, n.iddpt, n.idpadre,
n.ordender, n.ordenizq"
                . $checked
        )
            ->from('NomDpa n')->where($padre . ' AND (' . $strpadres . ')')->setHydrationMode(Doctrine::HYDRATE_ARRAY)
            ->execute();
    }

    /**
     * Obtiene los hijos
     *
     * @param int $idpadre Identificador padre
     *
     * @return array
     */
    public function getHijos($idpadre)
    {
        $q = Doctrine_Query::create();
        $result = $q->select('a.*, k.denominacion as tpest')
            ->from('NomDpa a')
            ->innerJoin('a.NomNivelestructural b on a.idnivelestructural=b.idnivelestructural')
            ->innerJoin('b.NomConceptonivel k ')
            ->where('a.idpadre = ? and iddpt <> idpadre', $idpadre)
            ->execute()->toArray();
        return $result;
    }

